BEGIN;
ALTER POLICY family_unions_authenticated_select ON public.family_unions TO authenticated USING (public.has_tree_access(tree_id, 'viewer'));
ALTER POLICY family_unions_authenticated_insert ON public.family_unions TO authenticated WITH CHECK (public.has_tree_access(tree_id, 'editor') AND EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_unions.partner1_id AND m.tree_id = family_unions.tree_id) AND (partner2_id IS NULL OR EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_unions.partner2_id AND m.tree_id = family_unions.tree_id)));
ALTER POLICY family_unions_authenticated_update ON public.family_unions TO authenticated USING (public.has_tree_access(tree_id, 'editor')) WITH CHECK (public.has_tree_access(tree_id, 'editor') AND EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_unions.partner1_id AND m.tree_id = family_unions.tree_id) AND (partner2_id IS NULL OR EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_unions.partner2_id AND m.tree_id = family_unions.tree_id)));
ALTER POLICY family_unions_authenticated_delete ON public.family_unions TO authenticated USING (public.has_tree_access(tree_id, 'editor'));
ALTER POLICY family_children_authenticated_select ON public.family_children TO authenticated USING (public.has_tree_access(tree_id, 'viewer'));
ALTER POLICY family_children_authenticated_insert ON public.family_children TO authenticated WITH CHECK (public.has_tree_access(tree_id, 'editor') AND EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_children.child_id AND m.tree_id = family_children.tree_id) AND EXISTS (SELECT 1 FROM public.family_unions u WHERE u.id = family_children.family_union_id AND u.tree_id = family_children.tree_id AND family_children.child_id <> u.partner1_id AND family_children.child_id IS DISTINCT FROM u.partner2_id));
ALTER POLICY family_children_authenticated_update ON public.family_children TO authenticated USING (public.has_tree_access(tree_id, 'editor')) WITH CHECK (public.has_tree_access(tree_id, 'editor') AND EXISTS (SELECT 1 FROM public.family_members m WHERE m.id = family_children.child_id AND m.tree_id = family_children.tree_id) AND EXISTS (SELECT 1 FROM public.family_unions u WHERE u.id = family_children.family_union_id AND u.tree_id = family_children.tree_id AND family_children.child_id <> u.partner1_id AND family_children.child_id IS DISTINCT FROM u.partner2_id));
ALTER POLICY family_children_authenticated_delete ON public.family_children TO authenticated USING (public.has_tree_access(tree_id, 'editor'));
ALTER POLICY "Users can upload family photos" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'family-photos' AND (storage.foldername(name))[1] = (select auth.uid())::text);
ALTER POLICY "Users can update family photos" ON storage.objects TO authenticated USING (bucket_id = 'family-photos' AND (storage.foldername(name))[1] = (select auth.uid())::text) WITH CHECK (bucket_id = 'family-photos' AND (storage.foldername(name))[1] = (select auth.uid())::text);
ALTER POLICY "Users can delete family photos" ON storage.objects TO authenticated USING (bucket_id = 'family-photos' AND (storage.foldername(name))[1] = (select auth.uid())::text);
